---daily pr re

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT 
    wu.vcemailid AS "Analyst Name", 
    ''AML Cases'' AS "Workflow Name", 
    SUM(CASE WHEN ActionV.text_ = ''notsuspicious'' THEN 1 ELSE 0 END) AS "#Closed Cases", 
    SUM(CASE WHEN ActionV.text_ = ''suspicioussendtodb'' THEN 1 ELSE 0 END) AS "#Cases Referred to DB", 
    SUM(CASE WHEN ActionV.text_ = ''suspicioussendtobranch'' THEN 1 ELSE 0 END) AS "#Cases Referred to Branch", 
    SUM(CASE WHEN ActionV.text_ = ''suspicious'' THEN 1 ELSE 0 END) AS "#Cases Escalated", 
    SUM(CASE WHEN ActionV.text_ IS NOT NULL THEN 1 ELSE 0 END) AS "Total Cases"
FROM 
    CAMUNDA.ACT_HI_TASKINST TASKL1L2 
LEFT JOIN 
    camunda.act_hi_varinst AS ActionV 
    ON TASKL1L2.proc_inst_id_ = ActionV.proc_inst_id_
    AND ActionV.name_ = ''Action''
     and actionv.var_type_=''string'' AND date(TASKL1L2 .end_time_) = :Date
JOIN ui.webuser wu ON wu.iuserid = CAST(TASKL1L2.assignee_ AS INTEGER) 
WHERE 
    TASKL1L2.NAME_ = ''Review Case By L1/ L2''
    AND TASKL1L2.assignee_ IS NOT NULL and
    taskl1l2.PROC_DEF_KEY_ = ''AMLCases''
    AND taskl1l2.tenant_id_ = :tenantidstr
GROUP BY 
    wu.vcemailid limit 1000;'::text WHERE
idashboardqueryid = 60 AND itenantid = 17;

UPDATE ui.dashboardquery SET
vcdashboardquery = 'select  
  wu.vcemailid as "Analyst Name", 
''AML Cases'' as  "Workflow Name",
sum(case when ActionV.text_=''notsuspicious'' then 1 else 0 end) as "#Closed Cases",
sum(case when ActionV.text_=''suspicioussendtodb'' then 1 else 0 end) as "#Cases Referred to DB",
sum(case when ActionV.text_=''suspicioussendtobranch'' then 1 else 0 end) as "#Cases Referred to Branch",
sum (case when ActionV.text_=''suspicious'' then 1 else 0 end) as "#Cases Escalated", 
sum(case when ActionV.text_ is not null then 1 else 0 end) as "Total Cases"
FROM (SELECT * FROM CAMUNDA.ACT_HI_PROCINST 
	WHERE PROC_DEF_KEY_=''AMLCasesPOBO'' and tenant_id_= :tenantidstr) AS PROC
INNER JOIN (SELECT distinct on (proc_inst_id_) * FROM CAMUNDA.ACT_HI_TASKINST WHERE NAME_ = ''Review Case By L1/ L2 POBO'' and assignee_ is not null order by proc_inst_id_, start_time_ desc) AS TASKL1L2
ON PROC.PROC_INST_ID_=TASKL1L2.PROC_INST_ID_
LEFT JOIN camunda.act_hi_varinst as ActionV
ON taskl1l2.proc_inst_id_=ActionV.proc_inst_id_ and ActionV.name_=''Action'' and date(ActionV.create_time_) = :Date
	JOIN ui.webuser wu ON wu.iuserid = CAST(taskl1l2.assignee_ AS INTEGER) 
group by wu.vcemailid limit 1000'::text WHERE
idashboardqueryid = 60 AND itenantid = 16;

UPDATE ui.dashboardquery SET
vcdashboardquery = 'select  
	 wu.vcemailid as "Analyst Name", 
	''AML Cases'' as  "Workflow Name",
sum(case when ActionV.text_=''notsuspicious'' then 1 else 0 end) as "#Closed Cases",
sum(case when ActionV.text_=''suspicioussendtodb'' then 1 else 0 end) as "#Cases Referred to DB",
sum(case when ActionV.text_=''suspicioussendtobranch'' then 1 else 0 end) as "#Cases Referred to Branch",
sum (case when ActionV.text_=''suspicious'' then 1 else 0 end) as "#Cases Escalated", 
sum(case when ActionV.text_ is not null then 1 else 0 end) as "Total Cases"
FROM (SELECT * FROM CAMUNDA.ACT_HI_PROCINST WHERE PROC_DEF_KEY_=''AMLCases'' and tenant_id_= :tenantidstr) AS PROC
INNER JOIN (SELECT distinct on (proc_inst_id_) * FROM CAMUNDA.ACT_HI_TASKINST WHERE NAME_ = ''Review Case By L1/ L2'' and assignee_ is not null order by proc_inst_id_, start_time_ desc) AS TASKL1L2
ON PROC.PROC_INST_ID_=TASKL1L2.PROC_INST_ID_
LEFT JOIN camunda.act_hi_varinst as ActionV
ON taskl1l2.proc_inst_id_=ActionV.proc_inst_id_ and ActionV.name_=''Action'' and date(ActionV.create_time_) = :Date
JOIN ui.webuser wu ON wu.iuserid = CAST(taskl1l2.assignee_ AS INTEGER) 
group by  wu.vcemailid limit 1000'::text WHERE
idashboardqueryid = 60 AND itenantid in (8, 23, 21, 22);

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
    "All":"WITH recursive raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.vcemailid AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask left join camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hiproc.tenant_id_ = :tenantidstr left join camunda.act_hi_detail hidetail ON hidetail.proc_inst_id_ = hiproc.proc_inst_id_ AND hidetail.name_ = ''userActivity'' AND hidetail.tenant_id_ = :tenantidstr left join ui.webuser assignee ON assignee.iuserid = cast(hitask.assignee_ as integer) left join ui.webusermapping groupmembership ON groupmembership.webuserid = assignee.iuserid AND groupmembership.mappingtype = ''Group'' AND groupmembership.mappingid != 1 AND groupmembership.itenantid = :tenantid left join ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid left join ui.workflowmasters workflow ON workflow.workflowkey = hiproc.proc_def_key_ AND workflow.itenantid = :tenantid WHERE hitask.end_time_ >= :Date and hitask.end_time_< (date(:Date) + interval ''1 day'') AND hitask.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hitask.assignee_ IS NOT NULL UNION SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.vcemailid AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask left join camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hiproc.tenant_id_ = :tenantidstr left join camunda.act_hi_detail hidetail ON hidetail.proc_inst_id_ = hiproc.proc_inst_id_ AND hidetail.name_ = ''userActivity'' left join ui.webuser assignee ON assignee.iuserid = CAST(hitask.assignee_ AS INTEGER) left join ui.webusermapping groupmembership ON groupmembership.webuserid = assignee.iuserid AND groupmembership.mappingtype = ''Group'' AND groupmembership.mappingid != 1 AND groupmembership.itenantid = :tenantid left join ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid left join ui.workflowmasters workflow ON workflow.workflowkey = hiproc.proc_def_key_ AND workflow.itenantid = :tenantid WHERE hidetail.time_ >= :Date and hidetail.time_< (date(:Date) + interval ''1 day'') AND hitask.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hitask.assignee_ IS NOT NULL ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(DISTINCT org.groupname, '', '') AS \\"User Group\\", org.taskname AS \\"Stage Name\\", COUNT(DISTINCT CASE WHEN org.endtime IS NOT NULL THEN org.taskid ELSE NULL END) AS \\"Cases Submitted\\", COUNT(DISTINCT CASE WHEN org.endtime IS NULL THEN org.taskid ELSE NULL END) AS \\"Claimed\\", COUNT(DISTINCT closedby.taskid) AS \\"Total Cases - Closed\\", org.workflowname AS \\"Workflow Name\\" FROM raw org LEFT join raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) AND closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname LIMIT 1000;",
    "Other":"WITH recursive raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.vcemailid AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask left join camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hiproc.tenant_id_ = :tenantidstr left join camunda.act_hi_detail hidetail ON hidetail.proc_inst_id_ = hiproc.proc_inst_id_ AND hidetail.name_ = ''userActivity'' AND hidetail.tenant_id_ = :tenantidstr left join ui.webuser assignee ON assignee.iuserid = cast(hitask.assignee_ as integer) left join ui.webusermapping groupmembership ON groupmembership.webuserid = assignee.iuserid AND groupmembership.mappingtype = ''Group'' AND groupmembership.mappingid != 1 AND groupmembership.itenantid = :tenantid left join ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid left join ui.workflowmasters workflow ON workflow.workflowkey = hiproc.proc_def_key_ AND workflow.itenantid = :tenantid WHERE hitask.end_time_ >= :Date and hitask.end_time_< (date(:Date) + interval ''1 day'') AND hitask.proc_def_key_ = :CaseType AND hitask.assignee_ IS NOT NULL UNION SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.vcemailid AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask left join camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hiproc.tenant_id_ = :tenantidstr left join camunda.act_hi_detail hidetail ON hidetail.proc_inst_id_ = hiproc.proc_inst_id_ AND hidetail.name_ = ''userActivity'' left join ui.webuser assignee ON assignee.iuserid = CAST(hitask.assignee_ AS INTEGER) left join ui.webusermapping groupmembership ON groupmembership.webuserid = assignee.iuserid AND groupmembership.mappingtype = ''Group'' AND groupmembership.mappingid != 1 AND groupmembership.itenantid = :tenantid left join ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid left join ui.workflowmasters workflow ON workflow.workflowkey = hiproc.proc_def_key_ AND workflow.itenantid = :tenantid WHERE hidetail.time_ >= :Date and hidetail.time_< (date(:Date) + interval ''1 day'') AND hitask.proc_def_key_ = :CaseType AND hitask.assignee_ IS NOT NULL ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(DISTINCT org.groupname, '', '') AS \\"User Group\\", org.taskname AS \\"Stage Name\\", COUNT(DISTINCT CASE WHEN org.endtime IS NOT NULL THEN org.taskid ELSE NULL END) AS \\"Cases Submitted\\", COUNT(DISTINCT CASE WHEN org.endtime IS NULL THEN org.taskid ELSE NULL END) AS \\"Claimed\\", COUNT(DISTINCT closedby.taskid) AS \\"Total Cases - Closed\\", org.workflowname AS \\"Workflow Name\\" FROM raw org left join raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) AND closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname LIMIT 1000;"
}
'::text WHERE
idashboardqueryid = 60 AND itenantid in (5,6,7,9,10, 12,13,14,15,19,20,24);

--case summary--
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": "WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \\"Claimed On\\", null as \\"Payer\\", null as  \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" , null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" FROM camunda.act_ru_task task LEFT JOIN camunda.act_id_user cuser ON task.assignee_ = cuser.id_ LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN camunda.act_hi_procinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) LEFT JOIN camunda.act_ru_variable TicketID ON TicketID.proc_inst_id_ = task.proc_inst_id_ AND TicketID.name_ = ''TicketID'' LEFT JOIN camunda.act_ru_variable Alert ON Alert.proc_inst_id_ = task.proc_inst_id_ AND Alert.name_ = ''Alert'' left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate) AND task.assignee_ IS NOT NULL AND hiproinst.proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 25000;",
        "Unclaimed": "WITH d1 AS (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow''), workflowkeys AS (SELECT workflowkey FROM ui.workflowmasters WHERE (workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1)) AND itenantid = :tenantid AND is_filter_display = true) select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", null as \\"Claimed On\\", null as \\"Payer\\", null as \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_  left join camunda.act_id_user cuser on task.assignee_=cuser.id_ right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_  left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' where (hiproinst.start_time_ between :StartDate AND  :EndDate) and task.assignee_ is null and hiproinst.proc_def_key_ in (SELECT workflowkey FROM workflowkeys) and hiproinst.tenant_id_= :tenantidstr limit 25000",
        "All": "WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ), workflowkeys AS ( SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid =  :tenantid AND is_filter_display = true ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ as \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) left JOIN camunda.act_hi_detail oplog ON oplog.id_ = ( SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1 ) left JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = ( SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1 ) LEFT JOIN ui.webuser clsuser ON clsuser.iuserid = CAST(closedby.assignee_ AS INTEGER) left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' left JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' left JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE ( hiproinst.start_time_ between :StartDate AND  :EndDate) AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ IN ( SELECT workflowkey FROM workflowkeys ) AND hiproinst.tenant_id_ = :tenantidstr  LIMIT 25000;",
        "Closed": "WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ), workflowkeys AS ( SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) left JOIN camunda.act_hi_detail oplog ON oplog.id_ = ( SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1 ) left JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = ( SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1 ) LEFT JOIN ui.webuser clsuser ON clsuser.iuserid = CAST(closedby.assignee_ AS INTEGER) left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' left JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' left JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE ( hiproinst.start_time_ between :StartDate AND  :EndDate ) AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ IN ( SELECT workflowkey FROM workflowkeys ) AND hiproinst.tenant_id_ = :tenantidstr  LIMIT 25000;"
    },
    "Other": {
        "Claimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", CASE WHEN task.assignee_ is not null THEN oplog.time_ ELSE null END  as \\"Claimed On\\", null as \\"Payer\\", null as  \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" , null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" FROM camunda.act_ru_task task LEFT JOIN camunda.act_id_user cuser ON task.assignee_ = cuser.id_ LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN camunda.act_hi_procinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN camunda.act_hi_detail oplog ON oplog.id_ = (SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1) LEFT JOIN camunda.act_ru_variable TicketID ON TicketID.proc_inst_id_ = task.proc_inst_id_ AND TicketID.name_ = ''TicketID'' LEFT JOIN camunda.act_ru_variable Alert ON Alert.proc_inst_id_ = task.proc_inst_id_ AND Alert.name_ = ''Alert'' left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address''  WHERE (hiproinst.start_time_ between :StartDate AND  :EndDate) AND task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ IS NOT NULL LIMIT 25000;", 
        "Unclaimed": "select task.name_ as \\"Stage\\", cuser.email_ as \\"Claimed By\\", hiproinst.start_time_ \\"Created Date\\", CASE WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \\"Status\\", pdef.name_ as \\"Case Type\\", null as \\"Claimed On\\", null as \\"Payer\\", null as \\"Payee\\", null as \\"Amount\\", TicketID.long_ as \\"Case ID\\", Alert.text_ as \\"Alert\\" , null as  \\"Closed Date\\" ,null as  \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ AS \\"Address\\" from camunda.act_ru_task task right join camunda.act_re_procdef pdef on pdef.id_ = task.proc_def_id_  left join camunda.act_id_user cuser on task.assignee_=cuser.id_ right join camunda.act_ru_variable  TicketID on TicketID.proc_inst_id_ = task.proc_inst_id_ and TicketID.name_ = ''TicketID'' full outer join camunda.act_ru_variable Alert on Alert.proc_inst_id_ = task.proc_inst_id_ and Alert.name_ = ''Alert'' inner join  camunda.act_hi_procinst hiproinst  on hiproinst.proc_inst_id_ = task.proc_inst_id_  left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' where (hiproinst.start_time_ between :StartDate AND  :EndDate) and task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) and task.assignee_ is null limit 25000",
        "All": " SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ as \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) left JOIN camunda.act_hi_detail oplog ON oplog.id_ = ( SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1 ) left JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = ( SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1 ) LEFT JOIN ui.webuser clsuser ON clsuser.iuserid = CAST(closedby.assignee_ AS INTEGER) left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' left JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' left JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE ( hiproinst.start_time_ between :StartDate AND  :EndDate) AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr  LIMIT 25000",
        "Closed": "SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN clsuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", basedon.text_ AS \\"Alert Type\\", address.text_ as \\"Address\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", null AS \\"Payer\\", null AS \\"Payee\\", null AS \\"Amount\\", ticketid.long_ AS \\"Case ID\\", alert.text_ AS \\"Alert\\" FROM camunda.act_hi_procinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) left JOIN camunda.act_hi_detail oplog ON oplog.id_ = ( SELECT id_ FROM camunda.act_hi_detail WHERE proc_inst_id_ = task.proc_inst_id_ AND name_ = ''userActivity'' ORDER BY time_ DESC LIMIT 1 ) left JOIN camunda.act_hi_taskinst closedby ON closedby.id_ = ( SELECT id_ FROM camunda.act_hi_taskinst WHERE proc_inst_id_ = hiproinst.proc_inst_id_ ORDER BY end_time_ DESC LIMIT 1 ) LEFT JOIN ui.webuser clsuser ON clsuser.iuserid = CAST(closedby.assignee_ AS INTEGER) left JOIN camunda.act_hi_varinst basedon ON basedon.proc_inst_id_ = hiproinst.proc_inst_id_ AND basedon.name_ = ''basedon'' left JOIN camunda.act_hi_varinst address ON address.proc_inst_id_ = hiproinst.proc_inst_id_ AND address.name_ = ''address'' left JOIN camunda.act_hi_varinst ticketid ON ticketid.proc_inst_id_ = hiproinst.proc_inst_id_ AND ticketid.name_ = ''TicketID'' left JOIN camunda.act_hi_varinst alert ON alert.proc_inst_id_ = hiproinst.proc_inst_id_ AND alert.name_ = ''Alert'' WHERE ( hiproinst.start_time_ between :StartDate AND  :EndDate) AND hiproinst.state_ != ''COMPLETED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr  LIMIT 25000"
   }
 }'::text WHERE
idashboardqueryid = 62 AND itenantid = 17;

---closed cases report

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
  "StartStage": { 
    "EndStage": {
      "ClosedOn": "  WITH ProcessInstances AS ( SELECT pinst.proc_inst_id_, pinst.start_time_ AS case_creation_time, pinst.end_time_ AS closed_on, pinst.state_ FROM camunda.act_hi_procinst pinst WHERE pinst.end_time_ >= :StartDate AND pinst.end_time_ <= :EndDate  AND pinst.proc_def_key_ = :CaseType AND pinst.tenant_id_ = :tenantidstr AND pinst.state_ = ''COMPLETED'' LIMIT :CountLimit ), LatestTask AS ( SELECT task.proc_inst_id_, task.id_ AS task_id, task.end_time_ AS task_end_time, task.assignee_, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst task WHERE task.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), StartStage AS ( SELECT startstage.proc_inst_id_, startstage.id_ AS start_stage_id, startstage.start_time_ AS start_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ ASC) AS rn FROM camunda.act_hi_taskinst startstage WHERE startstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), EndStage AS ( SELECT endstage.proc_inst_id_, endstage.id_ AS end_stage_id, endstage.start_time_ AS end_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ DESC) AS rn FROM camunda.act_hi_taskinst endstage WHERE endstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), OplogClaimStart AS ( SELECT oplogclaimstart.proc_inst_id_, oplogclaimstart.time_ AS start_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimstart WHERE oplogclaimstart.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimstart.name_ = ''userActivity'' AND cast(oplogclaimstart.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT start_stage_id FROM StartStage WHERE rn = 1) ), OplogClaimEnd AS ( SELECT oplogclaimend.proc_inst_id_, oplogclaimend.time_ AS end_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND cast(oplogclaimend.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) AS transaction_json FROM camunda.act_hi_varinst Txn LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", TransactionData.transaction_json -> ''observations'' -> ''payerVPA'' ->> ''externalId'' AS \\"Payer\\", TransactionData.transaction_json -> ''observations'' -> ''payeeVPA'' ->> ''externalId'' AS \\"Payee\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' END AS \\"VPA\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_time AS \\"End stage\\", CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE EXTRACT(DAY FROM (OplogClaimEnd.end_time - OplogClaimStart.start_time))::TEXT || '' days '' || TO_CHAR((OplogClaimEnd.end_time - OplogClaimStart.start_time), ''HH24:MI:SS'') END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ and task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ and startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ and endstage.rn = 1 LEFT JOIN ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER);",
      "CreatedOn": " WITH ProcessInstances AS ( SELECT pinst.proc_inst_id_, pinst.start_time_ AS case_creation_time, pinst.end_time_ AS closed_on, pinst.state_ FROM camunda.act_hi_procinst pinst WHERE pinst.start_time_ >= :StartDate AND pinst.start_time_ <= :EndDate  AND pinst.proc_def_key_ = :CaseType AND pinst.tenant_id_ = :tenantidstr AND pinst.state_ = ''COMPLETED'' LIMIT :CountLimit ), LatestTask AS ( SELECT task.proc_inst_id_, task.id_ AS task_id, task.end_time_ AS task_end_time, task.assignee_, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst task WHERE task.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), StartStage AS ( SELECT startstage.proc_inst_id_, startstage.id_ AS start_stage_id, startstage.start_time_ AS start_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ ASC) AS rn FROM camunda.act_hi_taskinst startstage WHERE startstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), EndStage AS ( SELECT endstage.proc_inst_id_, endstage.id_ AS end_stage_id, endstage.start_time_ AS end_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ DESC) AS rn FROM camunda.act_hi_taskinst endstage WHERE endstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), OplogClaimStart AS ( SELECT oplogclaimstart.proc_inst_id_, oplogclaimstart.time_ AS start_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimstart WHERE oplogclaimstart.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimstart.name_ = ''userActivity'' AND cast(oplogclaimstart.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT start_stage_id FROM StartStage WHERE rn = 1) ), OplogClaimEnd AS ( SELECT oplogclaimend.proc_inst_id_, oplogclaimend.time_ AS end_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND cast(oplogclaimend.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) AS transaction_json FROM camunda.act_hi_varinst Txn LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", TransactionData.transaction_json -> ''observations'' -> ''payerVPA'' ->> ''externalId'' AS \\"Payer\\", TransactionData.transaction_json -> ''observations'' -> ''payeeVPA'' ->> ''externalId'' AS \\"Payee\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' END AS \\"VPA\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_time AS \\"End stage\\", CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE EXTRACT(DAY FROM (OplogClaimEnd.end_time - OplogClaimStart.start_time))::TEXT || '' days '' || TO_CHAR((OplogClaimEnd.end_time - OplogClaimStart.start_time), ''HH24:MI:SS'') END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ and task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ and startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ and endstage.rn = 1 LEFT JOIN ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER);"
