ogClaimStart.start_time))::TEXT || '' days '' || TO_CHAR((OplogClaimEnd.end_time - OplogClaimStart.start_time), ''HH24:MI:SS'') END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ and task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ and startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ and endstage.rn = 1 LEFT JOIN ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER);",
      "CreatedOn": "  WITH ProcessInstances AS ( SELECT pinst.proc_inst_id_, pinst.start_time_ AS case_creation_time, pinst.end_time_ AS closed_on, pinst.state_ FROM camunda.act_hi_procinst pinst WHERE pinst.start_time_ >= :StartDate AND pinst.start_time_ <= :EndDate  AND pinst.proc_def_key_ = :CaseType AND pinst.tenant_id_ = :tenantidstr AND pinst.state_ = ''COMPLETED'' LIMIT :CountLimit ), LatestTask AS ( SELECT task.proc_inst_id_, task.id_ AS task_id, task.end_time_ AS task_end_time, task.assignee_, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst task WHERE task.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), StartStage AS ( SELECT startstage.proc_inst_id_, startstage.id_ AS start_stage_id, startstage.start_time_ AS start_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ ASC) AS rn FROM camunda.act_hi_taskinst startstage WHERE startstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) and name_ = :StartStage ), EndStage AS ( SELECT endstage.proc_inst_id_, endstage.id_ AS end_stage_id, endstage.start_time_ AS end_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ DESC) AS rn FROM camunda.act_hi_taskinst endstage WHERE endstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) and name_ = :EndStage), OplogClaimStart AS ( SELECT oplogclaimstart.proc_inst_id_, oplogclaimstart.time_ AS start_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimstart WHERE oplogclaimstart.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimstart.name_ = ''userActivity'' AND cast(oplogclaimstart.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT start_stage_id FROM StartStage WHERE rn = 1) ), OplogClaimEnd AS ( SELECT oplogclaimend.proc_inst_id_, oplogclaimend.time_ AS end_time, ROW_NUMBER() OVER (PARTITION BY cast(text_ as jsonb)->> ''id'' ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND cast(oplogclaimend.text_ as jsonb)->> ''action'' = ''Claim'' AND cast(text_ as jsonb)->> ''id'' in (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb) AS transaction_json FROM camunda.act_hi_varinst Txn LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", TransactionData.transaction_json -> ''observations'' -> ''payerVPA'' ->> ''externalId'' AS \\"Payer\\", TransactionData.transaction_json -> ''observations'' -> ''payeeVPA'' ->> ''externalId'' AS \\"Payee\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''vpa'' ->> ''vcexternaladdressid'' END AS \\"VPA\\", CASE WHEN jsonb_typeof(TransactionData.transaction_json) = ''array'' THEN TransactionData.transaction_json -> 0 -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' ELSE TransactionData.transaction_json -> ''observations'' -> ''account'' ->> ''vcexternalaccountid'' END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_time AS \\"End stage\\", CASE WHEN OplogClaimEnd.end_time IS NULL OR OplogClaimStart.start_time IS NULL OR OplogClaimEnd.end_time < OplogClaimStart.start_time THEN ''NA'' ELSE EXTRACT(DAY FROM (OplogClaimEnd.end_time - OplogClaimStart.start_time))::TEXT || '' days '' || TO_CHAR((OplogClaimEnd.end_time - OplogClaimStart.start_time), ''HH24:MI:SS'') END AS \\"Total time taken\\", assigneeuser.vcemailid AS \\"Closed By\\", pinst.closed_on AS \\"Closed On\\" FROM ProcessInstances pinst LEFT JOIN LatestTask task ON task.proc_inst_id_ = pinst.proc_inst_id_ and task.rn = 1 LEFT JOIN StartStage startstage ON startstage.proc_inst_id_ = pinst.proc_inst_id_ and startstage.rn = 1 LEFT JOIN EndStage endstage ON endstage.proc_inst_id_ = pinst.proc_inst_id_ and endstage.rn = 1 LEFT JOIN ui.ticketidgenerator TicketID ON TicketID.processinstanceid = pinst.proc_inst_id_ LEFT JOIN camunda.act_hi_varinst Alert ON Alert.proc_inst_id_ = pinst.proc_inst_id_ AND Alert.name_ = ''Alert'' AND Alert.var_type_ = ''string'' LEFT JOIN camunda.act_hi_varinst Amount ON Amount.proc_inst_id_ = pinst.proc_inst_id_ AND Amount.name_ = ''TransactionAmount'' AND Amount.var_type_ = ''double'' LEFT JOIN OplogClaimStart ON OplogClaimStart.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimStart.rn = 1 LEFT JOIN OplogClaimEnd ON OplogClaimEnd.proc_inst_id_ = pinst.proc_inst_id_ and OplogClaimEnd.rn = 1 LEFT JOIN TransactionData ON TransactionData.proc_inst_id_ = pinst.proc_inst_id_ LEFT JOIN ui.webuser assigneeuser ON assigneeuser.iuserid = CAST(task.assignee_ AS INTEGER);"
    }
  }
