        "Closed": " WITH filtered_hiproinst AS ( SELECT hiproinst.* FROM camunda.act_hi_procinst hiproinst WHERE hiproinst.start_time_ >= :StartDate   AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr LIMIT 30000 ), ranked_closedby AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_id_cte AS ( SELECT proc_inst_id_, long_ AS case_id FROM camunda.act_hi_varinst WHERE name_ = ''TicketID'' AND var_type_ IN (''long'', ''integer'') AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_cte AS ( SELECT proc_inst_id_, text_ AS alert FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), address_cte AS ( SELECT proc_inst_id_, text_ AS address FROM camunda.act_hi_varinst WHERE name_ = ''address'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), basedon_cte AS ( SELECT proc_inst_id_, text_ AS basedon FROM camunda.act_hi_varinst WHERE name_ = ''basedon'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", wu.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_id_cte.case_id AS \\"Case ID\\", alert_cte.alert AS \\"Alert\\", basedon_cte.basedon AS \\"Alert Type\\" , address_cte.address AS \\"Address\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ticket_id_cte ON ticket_id_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_cte ON alert_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN address_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN basedon_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ ;"
   }
 }'::text WHERE
idashboardqueryid = 62 AND itenantid in (12, 13, 15, 25);

